[
  {
    "url": "https://www.digital.go.jp/en/policies/mynumber/expiration-date",
    "title": "My Number Card and electronic certificate validity and renewals｜Digital Agency",
    "snippet": "If it is not written on the face of the card, you can check the expiration date of your Mynaportal by logging into Mynaportal and selecting \"My Number Card\" from the electronic certificate top page. PR materials Video My Number Card \"Expiration Date and Renewal\" (1 minute 20 seconds)",
    "published": null
  },
  {
    "url": "https://www.kojinbango-card.go.jp/en/",
    "title": "HOME – マイナンバーカード総合サイト",
    "snippet": "Validation period for Individual Number Card (My Number Card) is 10 years (5 years for persons under 20 years of age) and 5 years for the electronic certificate stored in the card.",
    "published": null
  },
  {
    "url": "https://en.namu.wiki/w/%EB%A7%88%EC%9D%B4%EB%84%98%EB%B2%84",
    "title": "my number - NamuWiki",
    "snippet": "Mar 8, 2026 Thanks to this, the validity period of the electronic certificate is 5 years, which is ample. As with public certificates, if an electronic signature is made using a My Number Card, it is treated as if it had been stamped with a personal seal.",
    "published": null
  },
  {
    "url": "https://mainichi.jp/english/articles/20250305/p2a/00m/0op/016000c",
    "title": "Do Japan's 'My Number' gov't ID cards expire in 5 years or 10? - The Mainichi",
    "snippet": "Mar 5, 2025 While the card itself is valid until the holder's 10th birthday after it was issued (or fifth for minors), the electronic certificate, which is used for various administrative procedures, expires ...",
    "published": null
  },
  {
    "url": "https://www.city.tsukuba.lg.jp/material/files/group/28/eigo.pdf",
    "title": "Published in October,2024 To All My Number Card Holders",
    "snippet": "An electronic certificate will be valid for five years from the date of issuance, until the holder's fifth birthday.",
    "published": null
  },
  {
    "url": "https://www.city.kodaira.tokyo.jp/kurashi/files/111532/111532/att_0000001.pdf",
    "title": "Period of Validity of the My Number Card and the electronic certificate",
    "snippet": "The IC chip in the My Number Card contains four pieces of personal information: name, address, date of birth, and gender, as well as electronic certificates (PIN).",
    "published": null
  },
  {
    "url": "https://en.wikipedia.org/wiki/My_Number_Card",
    "title": "My Number Card - Wikipedia",
    "snippet": "The My Number Card (Japanese: マイナンバーカード, Hepburn: mai nanbā kādo), officially Individual Number Card (Japanese: 個人番号カード, Hepburn: kojin bangō kādo), is an identity document issued to citizens of Japan and foreign residents which contains a unique 12-digit Individual Number (Japanese: 個人番号, Hepburn: kojin bangō)...",
    "published": null
  },
  {
    "url": "https://www.city.yokohama.lg.jp.e.sj.hp.transer.com/kurashi/koseki-zei-hoken/todokede/koseki-juminhyo/mynumber/MNCardSummary.html",
    "title": "About summary of my number card (electronic certificate) Yokohama-shi",
    "snippet": "Apr 11, 2024 ※If a person who has a My Number Card with two types of digital certificates reissues only the digital certificate for signature due to Address or change of name, the expiration date of the digital certificate for user certification is set as the expiration date of the digital certificate for signature to be reissued. In the event of an extension of the expiration date of the period of stay, acquisition of permanent residence, naturalization, or special period of stay, it is necessary to change the expiration date of My Number Card and reissue an electronic certificate.",
    "published": null
  },
  {
    "url": "https://akitajet.com/wiki/My_Number_Card",
    "title": "My Number Card - Akita Wiki",
    "snippet": "Please note that, while your My Number never expires, your My Number Card is only valid until the last day of the Period of Stay listed on your Residence Card. If you renew your period of stay, you will have to apply for a new My Number Card.",
    "published": null
  },
  {
    "url": "https://www.belongingjapan.com/how-to-guide/finance/my-number-card-japan/",
    "title": "My Number Card Japan: Complete Guide for Foreign Residents",
    "snippet": "Certified financial planner’s guide for foreign residents on My Number Card Japan. Learn how to apply, use, and manage your card for ID, healthcare, and taxes.",
    "published": null
  }
]
